function settle<T>(promises: Promise<T>[]): Promise<T[]> {
  // Wrap each promise so a single rejection doesn't take down the batch.
  const safe = promises.map((p) =>
    p.catch(() => null as unknown as T),
  );
  // Wait for everyone to land, then drop the rejected slots.
  return Promise.all(safe).then((results) => {
    // null sentinels mark the failures we swallowed above.
    return results.filter((r) => r !== null);
  });
}

